<style>
.reference-form-page{max-width:1100px;margin:0 auto;font-family:Poppins,sans-serif}.reference-form-heading{position:relative;display:flex;justify-content:center;align-items:center;margin:0 0 38px}.reference-form-heading h1{margin:0;font-size:38px;line-height:1.2;font-weight:700;color:#000}.status-pill{position:absolute;right:0}.form-alert{margin-bottom:16px;border-radius:6px;padding:12px 16px}.form-alert.success{background:#dcfce7;color:#166534}.form-alert.error{background:#fee2e2;color:#991b1b}.form-alert ul{margin:5px 0 0 20px}
.reference-form-page>form[enctype]{background:#fff;border-radius:11px;padding:10px 12px;box-shadow:0 3px 4px rgba(0,0,0,.24)}.reference-row{display:grid;grid-template-columns:250px minmax(0,1fr);align-items:start;gap:12px;padding:10px 0;font-size:15px}.reference-row>span:first-child{padding-top:11px}.reference-row input:not([type=radio]),.reference-row select,.reference-row textarea{box-sizing:border-box;width:100%;min-width:0;min-height:43px;border:0;border-radius:6px;background:#eeeeee;padding:10px 13px;color:#111;font:400 14px Poppins,sans-serif;outline:none}.reference-row textarea{min-height:106px;resize:vertical}.reference-row input:focus,.reference-row textarea:focus,.reference-row select:focus{box-shadow:0 0 0 2px #2653ff}.reference-row input[readonly],.reference-row textarea[readonly],.reference-row select:disabled{color:#111;opacity:1}
.document-row{grid-template-columns:250px minmax(0,1.4fr) 172px 260px;align-items:center}.document-row>span:first-child{padding-top:0}.document-row input[type=file]{height:43px;padding:4px;background:#eeeeee}.document-row input[type=file]::file-selector-button{height:35px;margin:-1px 8px -1px -1px;border:1px solid #d1d5db;background:#fff;padding:0 10px;font:400 13px Poppins,sans-serif}.document-actions{display:flex;gap:9px}.document-actions a,.document-actions button{display:grid;min-width:0;flex:1;height:43px;place-items:center;border:0;border-radius:5px;padding:0 12px;color:#fff;text-decoration:none;font:500 14px Poppins,sans-serif;cursor:pointer}.action-view{background:#2653ff}.action-change{background:#fd6eff}.action-delete,.wide-light{background:#7fa4e4}.action-upload{background:#ff0009!important}.wide-primary,.wide-draft,.wide-light{display:block;box-sizing:border-box;width:100%;min-height:43px;border:0;border-radius:5px;color:#fff;font:600 14px Poppins,sans-serif;cursor:pointer}.wide-primary{background:#2653ff}.wide-draft{background:#fd6eff}.inside-card,.indented{width:calc(100% - 250px);margin:4px 0 12px 250px}.category-row{align-items:center}.category-options{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.category-options label{display:flex;min-height:36px;align-items:center;justify-content:center;border-radius:5px;color:#fff;cursor:pointer}.category-options input{width:auto!important;min-height:auto!important;margin-right:6px}.outside-actions{display:grid;gap:20px;margin:48px -12px -185px;background:#f5f5f5;padding:38px 0 0}.reference-form-page:has(.outside-actions){padding-bottom:185px}.detail-card{margin:22px 0 0;border:0;padding:0}.detail-card legend{margin-bottom:8px;font-size:20px;font-weight:700}.target-row{padding-bottom:0}.hidden-form{display:none}.standalone-action{margin-top:38px}.back-overview{display:block;margin-top:20px;border-radius:5px;background:#2653ff;padding:12px;color:#fff;text-align:center;text-decoration:none;font-weight:600}.photo-button{margin-top:10px}
@media(max-width:1100px){.document-row{grid-template-columns:220px minmax(0,1fr) 160px 210px}.reference-row{grid-template-columns:220px minmax(0,1fr)}.inside-card,.indented{width:calc(100% - 220px);margin-left:220px}}
@media(max-width:800px){.reference-form-heading h1{font-size:30px}.status-pill{position:static;margin-left:10px}.reference-row,.document-row{grid-template-columns:1fr}.reference-row>span:first-child{padding-top:0}.document-actions{width:100%}.inside-card,.indented{width:100%;margin-left:0}.category-options{grid-template-columns:1fr 1fr}.outside-actions{margin-bottom:-185px}}
.super-review-actions{display:grid;gap:20px;margin:38px 0}.super-review-actions form{display:block;margin:0}.review-reject,.review-approve,.review-reject-confirm{display:flex;box-sizing:border-box;width:100%;min-height:43px;align-items:center;justify-content:center;border:0;border-radius:5px;padding:10px 20px;color:#fff;text-decoration:none;font:600 14px Poppins,sans-serif;cursor:pointer}.review-reject{background:#7fa4e4}.review-approve{background:#2653ff}.reject-reason{display:grid;grid-template-columns:1fr 230px;gap:10px}.reject-reason[hidden]{display:none}.reject-reason textarea{box-sizing:border-box;width:100%;min-height:70px;border:1px solid #cbd5e1;border-radius:6px;padding:10px;font:14px Poppins,sans-serif}.review-reject-confirm{background:#ff0009}@media(max-width:800px){.reject-reason{grid-template-columns:1fr}}
.super-panel .reference-row input[readonly],.super-panel .reference-row textarea[readonly],.super-panel .reference-row select:disabled{border:1px solid #111;background:#fff}.single-category{grid-template-columns:1fr}.single-category label{min-height:36px}.single-category input{display:none}
.phase-two-document{margin-top:18px;border-top:1px solid #d7dce3;padding-top:10px}.phase-document-note{grid-column:2/-1;margin:0;border-radius:6px;background:#f3f4f6;padding:11px 13px;color:#6b7280}.phase-document-name{display:flex;min-height:43px;box-sizing:border-box;align-items:center;border-radius:6px;background:#eeeeee;padding:10px 13px;color:#111}@media(max-width:800px){.phase-document-note{grid-column:auto}}
</style>
